package com.example.ai.api

import kotlinx.serialization.Serializable

/**
 * A todo on the wire. The same shape is used for create, edit, toggle and delete: a delete is a
 * newer version of the todo with [deletedAt] set (a tombstone), so one last-write-wins rule
 * covers every change.
 *
 * @property id UUID generated by the client, so a todo can be created offline.
 * @property createdAt epoch ms, client clock.
 * @property updatedAt epoch ms, client clock; the server keeps the version with the greater value.
 * @property deletedAt epoch ms of the deletion, `null` while the todo is alive.
 */
@Serializable
data class TodoDto(
    val id: String,
    val title: String,
    val description: String,
    val isDone: Boolean,
    val createdAt: Long,
    val updatedAt: Long,
    val deletedAt: Long?,
)
